133	    CHAOSPhysReg::generateRandomMask(std::mt19937 &gen, int bits_to_change, int len)
134	    {
135	        int mask = 0;
136	        std::uniform_int_distribution<int> bitDist(0, len - 1);
137	        while (bits_to_change-- > 0) mask |= (1 << bitDist(gen));
138	        return mask;
