369	    void
370	    CHAOSPhysReg::readTraceCheck()
371	    {
372	        // Poll the PhysRegFile's read counter for the INJECTED VALUE.
373	        // Counting stops once the slot is written (injected value destroyed),
374	        // so reads_before_overwrite = # reads of the injected value specifically.
375	        reads_before_overwrite = cpu->physRegFile().getReadsBeforeOverwrite();
376	        // Capture the cycle at the moment the value is overwritten (once).
377	        if (cpu->physRegFile().isTraceOverwritten() && !overwrite_recorded) {
378	            overwritten_at_cycle = cpu->curCycle();
379	            overwrite_recorded = true;
380	        }
381	        if (write_log) {
382	            *(log_stream->stream())
383	                << "ReadTracePoll: cycle " << cpu->curCycle()
384	                << " PhysReg[" << traced_phys_idx
385	                << "] reads_before_overwrite=" << reads_before_overwrite
386	                << " overwritten=" << (overwrite_recorded ? 1 : 0)
387	                << (overwrite_recorded ? (" at_cycle=" + std::to_string(overwritten_at_cycle)) : "")
388	                << std::endl;
389	        }
390	        bool any_active = false;
391	        for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
392	            gem5::ThreadContext *thread_context = cpu->getContext(tid);
393	            if (thread_context && thread_context->status() != ThreadContext::Halted) {
394	                any_active = true; break;
395	            }
396	        }
397	        if (any_active) {
398	            schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));
399	        } else {
400	            if (write_log) {
401	                *(log_stream->stream())
402	                    << "ReadTraceFinal: PhysReg[" << traced_phys_idx
403	                    << "] reads_before_overwrite=" << reads_before_overwrite
404	                    << " overwritten=" << (overwrite_recorded ? 1 : 0)
405	                    << (overwrite_recorded ? (" at_cycle=" + std::to_string(overwritten_at_cycle)) : "")
406	                    << " (workload halted)"
407	                    << std::endl;
408	            }
409	            cpu->physRegFile().clearReadTraceTarget();
410	            traced_phys_idx = -1;
411	        }
412	    }
